"""Assemble the scientific note from immutable receipts and calibrators, without reselecting a method."""
from base31 import D,P,read,save,sha,Path
from collections import Counter
LABEL={"first":"Начало сессии","last":"Конец сессии","win_bm":"BM25 по окнам","win_hybrid":"BM25 + E5 по окнам","turn_bm":"BM25 по репликам","turn_e5":"E5 по репликам","turn_hybrid":"BM25 + E5 по репликам","turn_late":"MaxSim по репликам","turn_ensemble":"Ансамбль без связи","turn_pair":"Совместный выбор Pair"}
def f(x,n=1):return f"{x:.{n}f}".replace(".",",")
def p(v):return f(100*v)
def it(c):
    lo,hi=c["interval"];return f"{p(c['delta'])} п.п. [{p(lo)} … {p(hi)}]"
def main():
    score=read(D/"score.json");su=score["summary"];co=score["contrasts"];fc=read(D/"forecast-seal.json");au=read(D/"blind-audit.json")
    lim=read(D/"attainable.json")["summary"];se=read(D/"semantic-audit.json");pos=read(D/"position-seal.json");review=se["graded"]
    blocks=[];add=blocks.append
    add("# Локализация факта внутри сессии агентной памяти")
    result=su["test/known/turn_pair"];a=su["test/known/win_hybrid"];b=su["test/known/turn_ensemble"];n=result["n"]
    add(f"На основной панели STALE из 320 ранее не изучавшихся сценариев и {n} вопросов обе точные цитаты доставлены в {result['both_full']}/{n} случаях при совместном выборе реплик, в {a['both_full']}/{n} при гибридном поиске по окнам и в {b['both_full']}/{n} при том же ансамбле без связи. В этом условии два адреса сессий уже известны от составителя теста. При самостоятельном выборе адресов соответствующие числа — {su['test/actual/turn_pair']['both_full']}, {su['test/actual/win_hybrid']['both_full']} и {su['test/actual/turn_ensemble']['both_full']} из {n}.")
    add("В первоначальном пилоте из восьми сценариев адреса обеих записей о состоянии находились чаще, чем в переданной выдержке одновременно помещались полные формулировки. Здесь взяли полную опубликованную коллекцию. Все прежние восемь попали в разведочную часть из 80 сценариев. Алгоритмы зафиксированы до оценки и не обучались на этом корпусе. Проверяется совместное извлечение пары подтверждений при одинаковых адресах, фактических затратах и вопросе. В STALE основная авторская метрика оценивает применение изменений в ответе на три разных вопроса. [Chao и соавт., STALE](https://arxiv.org/abs/2605.06527)")
    add("## Результаты на основной панели")
    tab=["| Политика передачи | Известны адреса — оба факта | Старый | Новый | Средняя доля слов | Найдены адреса — оба факта | Старый | Новый |",
         "|---|---:|---:|---:|---:|---:|---:|---:|"]
    for name,label in LABEL.items():
        x=su["test/known/"+name];y=su["test/actual/"+name]
        tab.append(f"| {label} | {x['both_full']} | {x['old_full']} | {x['new_full']} | {p(x['both_mean_cov']/n)}% | {y['both_full']} | {y['old_full']} | {y['new_full']} |")
    add("\n".join(tab))
    add("В каждой колонке с числом попаданий знаменатель 960. Средняя доля слов вычислена сначала отдельно для каждого из двух фактов, затем усреднена между ними. В основном сравнении обе стороны должны присутствовать полностью в текстах, прочитанных из соответствующих исходных сессий. Фразы без надёжного совпадения исходной авторской строки остаются в знаменателе. По всей коллекции точный исходный спан найден для "+str(score["exact_reference_coverage"]["old"])+"/400 старых и "+str(score["exact_reference_coverage"]["new"])+"/400 новых утверждений.")
    add("## Парные проверки и простые контроли")
    lines=[]
    for m in ("win_hybrid","turn_ensemble","first","last"):
        z=co["test/known/"+m+"/both_full"];zz=co["test/actual/"+m+"/both_full"]
        lines.append(f"- **Pair против «{LABEL[m]}»**. При заданных адресах {it(z)}, уровень {f(100*z['coverage'])}%. Число исходов в пользу Pair, против и равных по вопросам — {z['wins']}, {z['losses']}, {z['ties']}. При самостоятельном поиске {it(zz)}.")
    add("\n".join(lines))
    add("Интервалы рассчитаны повторной выборкой 320 целых сценариев, 10 000 повторов. В оценке двух исходных контрастов используется 97,5%-й интервал на каждый, в остальных — описательный 95%-й. Раннее и позднее окна добавлены как позиционные контроли до открытия разметки. Эта проверка существенна на синтетических диалогах, где место исходного утверждения может служить подсказкой. Все вторичные выборы лучшего метода по таблице описательны.")
    tt=[]
    for sk in ("dev","all"):
        vv=[su[sk+"/known/"+m]["both_full"] for m in ("turn_pair","turn_ensemble","win_hybrid","first","last")]
        tt.append(sk+" — "+"/".join(map(str,vv))+" из "+str(su[sk+"/known/turn_pair"]["n"]))
    add("Для совместного выбора / ансамбля без связи / гибридного окна / первого / последнего окна на известных адресах получены "+", ".join(tt)+". Распределения по SR, PR, IPA, T1 и T2 и все 24 000 записей доступны в score.json и score-rows.json.gz. Подсчёты по 400 сценариям включают основную панель и разведочную часть.")
    add("## Где теряется материал")
    pr=lim["test/known"];ac=su["test/actual/turn_pair"]
    add(f"Среди {n} вопросов при обычном поиске обе размеченные сессии оказались в выданной паре в {ac['both_source']} случаях. При предоставлении правильных двух сессий и том же точном бюджете диагностический выбор по верной разметке мог доставить обе цитаты в {pr['both_turn']} случаях среди всех окон, центрированных на репликах, и в {pr['both_grid']} среди всех окон с шагом 48. Когда начало окна ставится около границы известного целевого спана, это удаётся в {pr['both_gold_span']} случаях. Последняя цифра относится к трём заранее определённым позициям, поэтому это достижимый результат с привилегией, а не формальный максимум всех возможных подстрок.")
    add("## Калибровка семантической достаточности")
    add(f"Два независимо работавших агента Codex оценили 24 пары «утверждение — реальная выдержка» из разных проверочных сценариев. Они совпали в {se['agreement']}/24 случаях, κ Коэна {f(se['kappa'],2) if se['kappa'] is not None else 'не определена'}. По каждому решению о полной или частичной поддержке проверено буквальное вхождение выделенной оценщиком цитаты. Рецензенты видели только факт и выдержку. S — достаточное обоснование, P — содержательная частичная поддержка, N — отсутствие поддержки.")
    ta=["| Подборка по буквальному покрытию | N | Оба S | Оба P | Оба N | Разногласия |","|---|---:|---:|---:|---:|---:|"]
    for k,label in (("full","Полный спан"),("partial","Часть спана"),("zero_true","Ноль, правильная сессия"),("zero_other","Ноль, другой источник")):
        vs=[v for v in review if v["bucket"]==k];agree={l:sum(v["a"]==v["b"]==l for v in vs) for l in "SPN"}
        ta.append(f"| {label} | {len(vs)} | {agree['S']} | {agree['P']} | {agree['N']} | {len(vs)-sum(agree.values())} |")
    add("\n".join(ta));add("Равномерный отбор по видам буквального исхода намеренно изменяет распространённость категорий. Эти 24 оценки позволяют увидеть расхождения строгой метрики с достаточностью доказательства. Для количественного сравнения политик по смыслу требуется репрезентативная разметка с участием людей.")
    add("## Затраты и границы вывода")
    z=su["test/actual/turn_pair"];x=su["test/known/turn_pair"];tot=fc["totals"]
    add(f"Во внешнем контуре прочитаны {tot['n_sessions']} сессий и {tot['n_turns']} пользовательских реплик, отдельно закодированы {tot['n_window_candidates']} локальных окон затронутых сессий. На T320 одной паре соответствуют в среднем {f(x['tokens']/n,2)} нативных токена Qwen при заданных адресах и {f(z['tokens']/n,2)} при найденных. В каждую пару включены идентификаторы и даты. Длина каждой выдачи в каждом условии совпадает у всех 10 методов. Независимый аудит проверил {au['all_qwen_pair_receipts']} фактических двухчастных выдач, {au['unique_frames']} различных фрагментов и восстановил обычный прогноз при физическом исключении остальных вопросов и диагностических адресов в {len(au['isolated_checks'])} сценариях.")
    add("Глобальный гибрид сначала выбирает две разные сессии среди 50. Локальные окна привязаны к 96 токенам Qwen, у сетки шаг 48. Частная поздняя свёртка применяет MaxSim к эмбеддингам токенов замороженного E5-small-v2. Полноценный обученный ColBERT имеет собственные веса. Адресная информация от авторов доступна только для условной диагностики. GPU или внешние API для расчёта эмбеддингов и метрик не использовались. [ColBERT](https://arxiv.org/abs/2004.12832) · [E5](https://huggingface.co/intfloat/e5-small-v2)")
    (D/"REPORT_RU.md").write_text("\n\n".join(blocks)+"\n",encoding="utf8")
if __name__=="__main__":main()
